files.content:
:root {
  --bg: #1a1c2c;
  --panel: #2d2f4b;
  --text: #ffffff;
  --accent: #f6c945;
  --output: #7ef29a;
  --black: #000000;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family: 'Courier New', Courier, monospace;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.pixel-panel {
  background: var(--panel);
  border: 4px solid var(--text);
  box-shadow: 8px 8px 0 var(--black);
  padding: 2rem;
  width: min(100%, 430px);
}

h1 {
  margin: 0 0 1rem;
  font-size: 1.4rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  text-align: center;
}

.formula {
  background: #45496e;
  border: 2px solid var(--black);
  padding: 0.4rem;
  font-size: 0.85rem;
  margin: 0.4rem 0;
  text-align: center;
}

.field {
  margin: 1rem 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: bold;
  letter-spacing: 0.05em;
}

input,
select,
button,
output {
  width: 100%;
  font-family: inherit;
  font-size: 1rem;
  padding: 0.5rem;
  border: 3px solid var(--black);
  background: #ffffff;
  color: #1a1c2c;
  border-radius: 0;
}

input:focus,
select:focus,
button:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button {
  background: var(--accent);
  font-weight: bold;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--black);
  text-transform: uppercase;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.output-field output {
  display: block;
  min-height: 2.5rem;
  background: var(--bg);
  color: var(--output);
  border-color: var(--text);
  font-weight: bold;
}

'use strict';

const temperatureInput = document.getElementById('temperature');
const directionSelect = document.getElementById('direction');
const convertButton = document.getElementById('convert');
const resultOutput = document.getElementById('result');

function convertTemperature() {
  const rawValue = temperatureInput.value.trim();

  if (rawValue === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const value = Number(rawValue);

  if (!Number.isFinite(value)) {
    resultOutput.textContent = 'Error';
    return;
  }

  let converted;
  if (directionSelect.value === 'c-to-f') {
    converted = value * 9 / 5 + 32;
  } else {
    converted = (value - 32) * 5 / 9;
  }

  resultOutput.textContent = converted.toFixed(2);
}

convertButton.addEventListener('click', convertTemperature);

temperatureInput.addEventListener('keydown', (event) => {
  if (event.key === 'Enter') {
    convertTemperature();
  }
});
